function rngE(seed){ let a = seed >>> 0 || 1; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
/* spelling generator: homophone gap-fills (d1), spot the correct spelling (d2), type the word from its meaning (d3) */
function spellGen(d, seed){ const r = rngE(seed), pick = L => L[Math.floor(r() * L.length)];
  if (d === 1){ const P = pick(PAIRS), i = pick(P), w = HOMO[i]; return { d, k:"mcq", q:`Choose the right word: "${w[2]}"`, o:P.map(j => HOMO[j][0]), a:P.indexOf(i), x:`"${w[0]}" means: ${w[1]} ${P.filter(j => j !== i).map(j => `"${HOMO[j][0]}" means: ${HOMO[j][1]}`).join(" ")}` }; }
  if (d === 2){ const w = pick(SPELL), wr = MISS[w[0]] || []; const o = [w[0]].concat(wr), sh = o.slice().sort(() => r() - .5);
    return { d, k:"mcq", q:`Which spelling is correct? (Meaning: ${w[1]})`, o:sh, a:sh.indexOf(w[0]), x:`The correct spelling is "${w[0]}". ${TIPS[w[0]] || "Break it into syllables and say each part as you write."}` }; }
  const pool = r() < .5 ? SPELL : HOMO.map(h => [h[0], h[1]]), w = pick(pool);
  return { d, k:"text", q:`Type the word that means: "${w[1]}"${HOMO.some(h => h[0] === w[0]) ? " (careful: it's a homophone!)" : ""}`, a:[w[0], w[0].toLowerCase()], best:w[0], x:`The word is "${w[0]}". ${TIPS[w[0]] || ""}` };
}
