   tasks:[ m(1, "What is the plural of 'fox'?", "foxes", ["foxs", "foxies", "foxen"], "Ends in x → add -es."), m(1, "What is the plural of 'city'?", "cities", ["citys", "cityes", "citties"], "Consonant + y → ies."), m(1, "What is the plural of 'monkey'?", "monkeys", ["monkies", "monkeyes", "monkeis"], "Vowel + y → just add s."), tx(1, "Type the plural of 'knife'.", ["knives"], "f/fe → ves: knives."), m(2, "Which plural is spelled correctly?", "tomatoes", ["tomatos", "tomatoe", "tomatose"], ""), m(2, "What is the plural of 'child'?", "children", ["childs", "childes", "childrens"], "An irregular plural."), tx(2, "Add -ing to 'shine'.", ["shining"], "Drop the e before a vowel suffix."), m(2, "Which word is spelled correctly?", "beautiful", ["beautifull", "beautyful", "beutiful"], "y → i, and -ful has one l."), tx(3, "Add -ed to 'stop'.", ["stopped"], "Short vowel + single consonant → double it."), m(3, "Which plural is WRONG?", "roofes", ["roofs", "leaves", "chiefs"], "Roof just adds -s.") ],
