U.y8revhistory = { name:"History: Term 1 Revision", short:"History", year:8, revision:true, icon:"🏛", colour:"#6B4E2E",
  blurb:"4.3 The New Model Army, 4.4 Charles I's trial and execution, 4.6 Cromwell: the man who banned Christmas", topics:[
 T({ id:"nma", focus:true, title:"⚔️ What was new about the New Model Army?", strand:R + " · 4.3",
   ideas:["The English Civil War (1642–1651) was fought between Royalists (Cavaliers, for Charles I) and Parliamentarians (Roundheads).","In 1645 Parliament created the New Model Army: Britain's first full-time, professional, national army, led by Sir Thomas Fairfax with Oliver Cromwell commanding the cavalry.","What was new: soldiers were trained, disciplined and paid regularly; promotion was by ability, not birth or wealth; they wore the same red uniform; strict rules banned swearing, drinking and looting.","Many soldiers were Puritans who believed they were fighting for God — they sang psalms before battle and were highly motivated.","Results: decisive victories at Naseby (June 1645) and Langport, which effectively won the first Civil War for Parliament."],
   example:"Why was the New Model Army so successful at Naseby (1645)?\nIt was well trained and disciplined, so Cromwell's cavalry regrouped after charging instead of chasing the enemy.\nThey then attacked the Royalist infantry, winning the battle.",
   more:[ ex("How do you answer 'What was new about…?' (explain question)", ["Identify 2–3 new features (paid regularly, promotion by ability, uniform, discipline).","For each, explain how it was different from before (old armies were local, part-time, led by nobles).","Explain the effect: why it made the army more effective.","Use specific evidence, e.g. the Battle of Naseby."], "Feature → how it was different → why it mattered") ],
   fun:"The New Model Army's red coats were the start of the famous British 'redcoat' uniform worn for the next 200 years!", trick:"New Model Army = 'PPP': Paid, Professional, Promotion on merit.",
   tasks:[ m(1, "In which year was the New Model Army created?", "1645", ["1642", "1649", "1660"], ""), m(1, "Which side did the New Model Army fight for?", "Parliament (Roundheads)", ["The King (Cavaliers)", "Scotland", "France"], ""), m(1, "Who was the New Model Army's commander-in-chief?", "Sir Thomas Fairfax", ["Charles I", "Prince Rupert", "James I"], "Cromwell led the cavalry."), m(1, "What colour uniform did the New Model Army wear?", "Red", ["Blue", "Green", "Black"], ""), m(2, "How were officers promoted in the New Model Army?", "By ability and skill, not by noble birth", ["Only nobles could lead", "By paying money", "By age"], ""), m(2, "Which battle in 1645 was a decisive New Model Army victory?", "Naseby", ["Hastings", "Bosworth", "Waterloo"], ""), m(2, "Why were soldiers paid regularly?", "To keep them loyal and stop them looting or leaving", ["To make them rich", "To buy horses", "It wasn't important"], ""), m(3, "Why did religion make the New Model Army strong?", "Many Puritan soldiers believed God was on their side, so morale was high", ["They were all priests", "They didn't believe in God", "The King paid them"], ""), m(3, "How was the New Model Army different from earlier armies?", "Full-time and national, instead of part-time local militias led by nobles", ["It had no horses", "It was smaller", "It fought for the King"], ""), m(3, "Which was the MOST important reason for its success? A strong answer…", "Explains several features (pay, discipline, training, leadership, belief) and judges which mattered most", ["Picks one with no reason", "Only gives dates", "Says it was luck"], "") ],
   pool:[ m(1, "Who led the cavalry (horse soldiers) in the New Model Army?", "Oliver Cromwell", ["Charles I", "Fairfax", "Rupert"], "His cavalry were called the 'Ironsides'."), m(2, "What rules did soldiers have to follow?", "No swearing, drinking or looting", ["No marching", "No praying", "No uniforms"], ""), m(3, "Why was it significant that it was a NATIONAL army?", "Soldiers would fight anywhere in the country, not just defend their own area", ["It was paid by the King", "It only fought abroad", "It was smaller"], "") ] }),
 T({ id:"trial", title:"👑⚖️ Why was King Charles I sentenced to death?", strand:R + " · 4.4",
   ideas:["Charles I believed in the Divine Right of Kings: God chose him, so he answered only to God, not Parliament.","Causes of conflict: money (Ship Money tax without Parliament), religion (Charles's Catholic wife and high-church changes angered Puritans), power (ruled without Parliament 1629–1640, tried to arrest five MPs in 1642).","After losing the first Civil War, Charles plotted with the Scots and started a Second Civil War (1648). Many in the army saw him as a 'man of blood'.","Parliament was purged (Pride's Purge, December 1648), leaving the 'Rump Parliament' which set up a High Court to try the King for treason.","Charles refused to accept the court's authority. He was found guilty and beheaded outside the Banqueting House, Whitehall, on 30 January 1649. 59 commissioners signed the death warrant, including Cromwell."],
   example:"Why was the trial of Charles I so shocking?\nNo English monarch had ever been put on trial by their own people.\nIt challenged the Divine Right of Kings: it showed a king could be held to account.",
   more:[ ex("How do you answer 'Why was Charles I executed?' (several causes)", ["Long-term: clashes over money, religion and power.","Short-term: he lost the war but kept plotting (Second Civil War).","Trigger: the army and Rump Parliament decided he couldn't be trusted.","Judge: which cause was most important, and why."], "Long-term + short-term + trigger + judgement") ],
   fun:"Charles I wore two shirts to his execution on a freezing January day so that he wouldn't shiver — he didn't want people to think he was afraid!", trick:"MRP = the 3 clashes: Money, Religion, Power.",
   tasks:[ n(1, "In which year was Charles I executed?", 1649, "30 January 1649."), m(1, "What was the 'Divine Right of Kings'?", "The belief that kings were chosen by God and answered only to God", ["Parliament chose the king", "Kings had to be elected", "A tax"], ""), m(1, "What was Charles found guilty of?", "Treason", ["Theft", "Murder in a duel", "Witchcraft"], ""), m(1, "Where was Charles I executed?", "Outside the Banqueting House, Whitehall, London", ["The Tower of London", "Edinburgh", "Naseby"], ""), m(2, "What was Ship Money?", "A tax Charles collected without Parliament's agreement", ["Money for sailors", "A gift to France", "A loan"], ""), m(2, "Why did Charles's religious changes anger Puritans?", "They seemed too close to Catholicism", ["They were too strict", "They banned churches", "They were Puritan"], ""), m(2, "What happened in 1642 that helped start the war?", "Charles tried to arrest five MPs in Parliament", ["He won a battle", "He married", "He signed a treaty"], ""), m(3, "Why did the army decide Charles had to die?", "He kept plotting and started a Second Civil War, so he couldn't be trusted", ["He won the war", "He became Puritan", "He asked to die"], ""), m(3, "What was Pride's Purge (1648)?", "Soldiers removed MPs who still wanted to negotiate with the King", ["A new tax", "A battle", "A royal wedding"], ""), m(3, "Why did Charles refuse to plead at his trial?", "He said no court had the authority to try a king", ["He was ill", "He admitted guilt", "He didn't speak English"], "") ],
   pool:[ m(1, "Who signed Charles I's death warrant, among others?", "Oliver Cromwell", ["Charles II", "Elizabeth I", "James I"], "59 commissioners signed it."), m(2, "What was the 'Rump Parliament'?", "The MPs left after Pride's Purge", ["The House of Lords", "A Royalist group", "A Scottish parliament"], ""), m(3, "Why was the execution significant for the future?", "It showed that rulers could be held accountable to Parliament and the people", ["It made kings stronger", "Nothing changed", "It started the Tudors"], "") ] }),
 T({ id:"cromwell", title:"🎄🚫 Cromwell: the man who banned Christmas", strand:R + " · 4.6",
   ideas:["After Charles I's execution, England became a republic (the Commonwealth). In 1653 Oliver Cromwell became Lord Protector.","Cromwell was a Puritan. Puritans wanted a simple, strict, 'pure' way of life focused on God.","Puritan rules: Christmas celebrations were banned (from 1644, by Parliament, and enforced under Cromwell) because they were seen as wasteful and not in the Bible; theatres were closed; many sports and dancing on Sundays were banned; plain clothes were encouraged.","Hero or villain? Supporters: strong leader, religious freedom for many Protestants, readmitted Jews to England (1656), strong navy. Critics: brutal in Ireland (Drogheda, 1649), dismissed Parliament, ruled like a king.","After Cromwell died (1658), his son Richard couldn't hold power. The monarchy was restored in 1660 with Charles II, and Christmas came back!"],
   example:"Why did Puritans ban Christmas?\nThey thought the celebrations had become an excuse for drinking, feasting and bad behaviour.\nChristmas wasn't mentioned as a feast in the Bible.\nSo they wanted it to be a normal working day.",
   more:[ ex("How do you answer 'Was Cromwell a hero or a villain?'", ["Give hero evidence (strong leader, readmitted Jews, won the war).","Give villain evidence (Ireland, banned fun, ruled like a king).","Consider who is judging: Puritans, Royalists, Irish Catholics.","Give a balanced final judgement."], "Both sides + perspective + judgement") ],
   fun:"Cromwell asked to be painted 'warts and all' — he wanted an honest portrait, not a flattering one!", trick:"Puritan = PURE: Plain clothes, Unfun rules (no Christmas, no theatre), Religion first, Every Sunday for God.",
   tasks:[ m(1, "What title did Cromwell take in 1653?", "Lord Protector", ["King", "Prime Minister", "Emperor"], ""), m(1, "What religious group did Cromwell belong to?", "Puritans", ["Catholics", "Quakers", "Anglicans only"], ""), m(1, "Which celebration did the Puritans ban?", "Christmas", ["Birthdays", "Weddings", "Easter Sunday church"], ""), n(1, "In which year was the monarchy restored?", 1660, "Charles II became king."), m(2, "Why did Puritans close theatres?", "They saw plays as sinful and a distraction from God", ["They were too expensive", "There was a plague", "Actors went on strike"], ""), m(2, "What happened at Drogheda (1649)?", "Cromwell's army killed thousands of soldiers and civilians in Ireland", ["Cromwell lost a battle", "A peace treaty was signed", "Christmas was restored"], ""), m(2, "What happened after Cromwell died in 1658?", "His son Richard failed to rule, and the monarchy returned in 1660", ["Cromwell's son ruled for 20 years", "England joined France", "Puritans took over"], ""), m(3, "Which is evidence Cromwell was a hero?", "He allowed Jews to return to England and gave religious freedom to many Protestants", ["He dismissed Parliament", "He banned Christmas", "His army's actions in Ireland"], ""), m(3, "Why is Cromwell's reputation still debated?", "People judge him differently depending on their beliefs and which actions they focus on", ["There is no evidence", "He was always popular", "Historians all agree"], ""), m(3, "Why did many ordinary people dislike Puritan rule?", "Popular fun — Christmas, theatre, sports — was banned", ["Taxes were removed", "They got more holidays", "Food was free"], "") ],
   pool:[ m(1, "What was the Commonwealth?", "The period when England was a republic (1649–1660)", ["A trade group", "A Tudor law", "A church"], ""), m(2, "What did Cromwell do to Parliament in 1653?", "He dismissed the Rump Parliament with soldiers", ["He made it bigger", "He became an MP", "He nothing"], ""), m(3, "Why might Royalists see Cromwell as a villain?", "He helped execute the King and ruled like a dictator", ["He brought back Christmas", "He was a Royalist", "He restored Charles II"], "") ] })
]};

